    #[test]
    fn recovery_invalidation_retires_old_live_allocator_before_replacement() {
        let dir = tempfile::tempdir().expect("tempdir");
        let db_path = dir.path().join("recovered-allocator.sqlite3");
        std::fs::File::create(&db_path).expect("create allocator identity fixture");
        let config = DbPoolConfig {
            database_url: format!("sqlite:///{}", db_path.display()),
            storage_root: Some(dir.path().join("storage")),
            min_connections: 0,
            max_connections: 1,
            run_migrations: false,
            warmup_connections: 0,
            ..Default::default()
        };
        let old_pool = DbPool::new(&config).expect("create pre-recovery pool");
        let old_allocator = old_pool.message_id_allocator();
        let identity = normalize_sqlite_identity_path_buf(&db_path);
        assert!(
            invalidate_file_message_id_allocator(&identity),
            "the live file identity must be present before invalidation"
        );

        let replacement = DbPool::new(&config).expect("create replacement pool");
        assert!(
            !Arc::ptr_eq(&old_allocator, &replacement.message_id_allocator()),
            "post-recovery pools must not inherit the old archive seed/high-water state"
        );
        assert_ne!(old_pool.cache_generation, replacement.cache_generation);

        let replacement_allocator = replacement.message_id_allocator();
        let storage_root = config.resolved_storage_root();
        let barrier = Arc::new(std::sync::Barrier::new(3));
        let old_barrier = Arc::clone(&barrier);
        let old_storage_root = storage_root.clone();
        let old_handle = std::thread::spawn(move || {
            let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
                .build()
                .expect("build old allocator runtime");
            old_barrier.wait();
            runtime.block_on(async move {
                let cx = Cx::current().expect("runtime installs allocator context");
                old_allocator.allocate(&cx, 0, &old_storage_root).await
            })
        });
        let replacement_barrier = Arc::clone(&barrier);
        let replacement_handle = std::thread::spawn(move || {
            let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
                .build()
                .expect("build replacement allocator runtime");
            replacement_barrier.wait();
            runtime.block_on(async move {
                let cx = Cx::current().expect("runtime installs allocator context");
                replacement_allocator.allocate(&cx, 0, &storage_root).await
            })
        });
        barrier.wait();

        assert!(matches!(
            old_handle.join().expect("join old allocator"),
            Outcome::Err(error) if error.to_string().contains("retired after database recovery")
        ));
        assert!(matches!(
            replacement_handle
                .join()
                .expect("join replacement allocator"),
            Outcome::Ok(1)
        ));
    }

    #[test]
    fn message_creation_routes_through_shared_reuse_proof_allocator() {
        // mcp_agent_mail#176: message creation must allocate ids through the
        // shared monotonic allocator (so a regressed durable sequence cannot
        // re-issue a canonical id), and every wrapper of the same underlying
        // pool must share one high-water mark.
        let dir = tempfile::tempdir().expect("tempdir");
        let db_path = dir.path().join("alloc_route.sqlite3");
        let cfg = DbPoolConfig {
            database_url: format!("sqlite:///{}", db_path.display()),
            storage_root: Some(dir.path().join("storage")),
            min_connections: 1,
            max_connections: 1,
            warmup_connections: 0,
            ..Default::default()
        };
        let pool = get_or_create_pool(&cfg).expect("create pool");
        // A second wrapper of the same cached pool shares the allocator.
        let pool2 = get_or_create_pool(&cfg).expect("reuse cached pool");
        assert!(
            Arc::ptr_eq(&pool.message_id_allocator(), &pool2.message_id_allocator()),
            "wrappers of the same cached pool must share one allocator"
        );

        let rt = asupersync::runtime::RuntimeBuilder::current_thread()
            .build()
            .expect("build runtime");

        rt.block_on(async {
            let cx = Cx::current().expect("runtime installs message test context");
            let project =
                crate::queries::ensure_project(&cx, &pool, "/data/projects/am-alloc-route")
                    .await
                    .into_result()
                    .expect("ensure project");
            let project_id = project.id.expect("project id");
            let sender = crate::queries::register_agent(
                &cx,
                &pool,
                project_id,
                "BlueLake",
                "codex-cli",
                "gpt-5",
                Some("alloc-route"),
                Some("auto"),
                None,
            )
            .await
            .into_result()
            .expect("register sender");
            let sender_id = sender.id.expect("sender id");

            let first = crate::queries::create_message(
                &cx, &pool, project_id, sender_id, "one", "body", None, "normal", false, "{}",
            )
            .await
            .into_result()
            .expect("first message");
            assert_eq!(first.id, Some(1));
            // The allocator handed out id 1 and tracks it — proving the create
            // path routes through it rather than relying solely on the live
            // SQLite's AUTOINCREMENT.
            assert_eq!(pool.message_id_allocator().current_high_water(), 1);

            let second = crate::queries::create_message(
                &cx, &pool, project_id, sender_id, "two", "body", None, "normal", false, "{}",
            )
            .await
            .into_result()
            .expect("second message");
            assert_eq!(second.id, Some(2));
            // Tracked on the wrapper that shares the same Arc — proving the
            // high-water is process-wide for this database, not per-wrapper.
            assert_eq!(pool2.message_id_allocator().current_high_water(), 2);

            // The allocator's reuse-proofness when the durable sequence
            // regresses (the actual #176 suspect-mode failure) is covered by
            // the `id_floor::tests::allocator_reuse_proof_when_durable_floor_regresses`
            // unit test; here we have established that message creation routes
            // through that same shared allocator.
        });
    }

    /// Expected runtime `PRAGMA busy_timeout` fragment, derived from the
    /// shared ecosystem constant (br-ovy6e).
    fn runtime_busy_timeout_pragma() -> String {
        format!(
            "busy_timeout = {}",
            mcp_agent_mail_core::config::DB_RUNTIME_BUSY_TIMEOUT_MS
        )
    }

    /// Verify PRAGMA settings use the runtime busy timeout, ordered before
    /// `journal_mode` so lock waits already apply to the WAL switch (br-ovy6e).
    #[test]
    fn pragma_busy_timeout_matches_runtime_constant() {
        let busy_pragma = runtime_busy_timeout_pragma();
        let sql = schema::init_schema_sql();
        let busy_idx = sql
            .find(&busy_pragma)
            .expect("schema init sql must contain the runtime busy_timeout");
        let wal_idx = sql
            .find("journal_mode = WAL")
            .expect("schema init sql must contain journal_mode=WAL");
        assert!(
            busy_idx < wal_idx,
            "busy_timeout must be set before journal_mode to avoid SQLITE_BUSY before timeout applies"
        );
        assert!(
            sql.contains("journal_mode = WAL"),
            "WAL mode is required for concurrent access"
        );

        let init_sql = schema::PRAGMA_DB_INIT_SQL;
        let init_busy_idx = init_sql
            .find(&busy_pragma)
            .expect("startup init SQL must contain the runtime busy_timeout");
        let init_wal_idx = init_sql
            .find("journal_mode = WAL")
            .expect("startup init SQL must contain journal_mode=WAL");
        assert!(
            init_busy_idx < init_wal_idx,
            "startup init must set busy_timeout before switching journal_mode"
        );
        assert!(
            !init_sql.contains("DELETE"),
            "runtime startup init must not force rollback-journal mode"
        );
    }

    /// br-ovy6e: every runtime pragma bundle must carry the shared runtime
    /// busy timeout, which in turn must stay below the 30s ecosystem client
    /// deadline so a lock-contended query gives up before its dispatch thread
    /// is abandoned. A live connection check proves the pragma actually takes
    /// effect, not just that the SQL text mentions it.
    #[test]
    fn runtime_pragma_bundles_use_runtime_busy_timeout() {
        let busy_pragma = runtime_busy_timeout_pragma();
        const {
            assert!(
                mcp_agent_mail_core::config::DB_RUNTIME_BUSY_TIMEOUT_MS
                    < mcp_agent_mail_core::config::ECOSYSTEM_CLIENT_DEADLINE_MS,
                "runtime busy_timeout must stay below the ecosystem client deadline"
            );
        }
        for (name, sql) in [
            (
                "PRAGMA_SETTINGS_SQL",
                schema::PRAGMA_SETTINGS_SQL.to_string(),
            ),
            ("PRAGMA_DB_INIT_SQL", schema::PRAGMA_DB_INIT_SQL.to_string()),
            (
                "PRAGMA_CONN_SETTINGS_SQL",
                schema::PRAGMA_CONN_SETTINGS_SQL.to_string(),
            ),
            (
                "build_conn_pragmas",
                schema::build_conn_pragmas(4, schema::DEFAULT_CACHE_BUDGET_KB),
            ),
        ] {
            assert!(
                sql.contains(&busy_pragma),
                "{name} must use the runtime busy_timeout ({busy_pragma}): {sql}"
            );
        }

        // The recovery/export-only base bundle deliberately keeps the longer
        // 60s wait: it runs outside any dispatch deadline.
        assert!(
            schema::PRAGMA_DB_INIT_BASE_SQL.contains("busy_timeout = 60000"),
            "one-shot recovery bundle intentionally keeps the 60s busy_timeout"
        );

        // Live check: applying the per-connection bundle must leave the
        // runtime busy_timeout configured on the connection.
        let dir = tempfile::tempdir().expect("tempdir");
        let db_path = dir.path().join("runtime_busy_timeout.db");
        let db_path_str = db_path.to_str().expect("utf8 db path");
        let conn =
            open_sqlite_file_with_lock_retry(db_path_str).expect("open runtime sqlite connection");
        conn.execute_raw(schema::PRAGMA_CONN_SETTINGS_SQL)
            .expect("apply per-connection pragmas");
        let configured = read_pragma_i64(&conn, "PRAGMA busy_timeout;", "timeout")
            .expect("read configured busy_timeout");
        assert_eq!(
            configured, REQUIRED_STARTUP_BUSY_TIMEOUT_MS,
            "live connection busy_timeout must match the runtime constant"
        );
    }

    /// Verify warmup opens the requested number of connections.
