    /// Verify `build_conn_pragmas` scales `cache_size` with pool size.
    #[test]
    fn build_conn_pragmas_budget_aware_cache() {
        // 100 connections: 512*1024 / 100 = 5242 KB each
        let sql_100 = schema::build_conn_pragmas(100, schema::DEFAULT_CACHE_BUDGET_KB);
        assert!(
            sql_100.contains("cache_size = -5242"),
            "100 conns should get ~5MB each: {sql_100}"
        );

        // 25 connections: 512*1024 / 25 = 20971 KB each
        let sql_25 = schema::build_conn_pragmas(25, schema::DEFAULT_CACHE_BUDGET_KB);
        assert!(
            sql_25.contains("cache_size = -20971"),
            "25 conns should get ~20MB each: {sql_25}"
        );

        // 1 connection: 512*1024 / 1 = 524288 KB → clamped to 65536 (64MB max)
        let sql_1 = schema::build_conn_pragmas(1, schema::DEFAULT_CACHE_BUDGET_KB);
        assert!(
            sql_1.contains("cache_size = -65536"),
            "1 conn should get 64MB (clamped max): {sql_1}"
        );

        // 500 connections: clamped to 2MB min
        let sql_500 = schema::build_conn_pragmas(500, schema::DEFAULT_CACHE_BUDGET_KB);
        assert!(
            sql_500.contains("cache_size = -2048"),
            "500 conns should get 2MB (clamped min): {sql_500}"
        );

        // All should have journal_size_limit
        for sql in [&sql_100, &sql_25, &sql_1, &sql_500] {
            assert!(
                sql.contains("journal_size_limit = 268435456"),
                "all should have 256MB journal_size_limit"
            );
            assert!(
                sql.contains(&runtime_busy_timeout_pragma()),
                "must have the runtime busy_timeout"
            );
            assert!(
                sql.contains("mmap_size = 268435456"),
                "must have 256MB mmap"
            );
        }
    }

    /// Verify `build_conn_pragmas` handles zero pool size gracefully.
    #[test]
    fn build_conn_pragmas_zero_pool_fallback() {
        let sql = schema::build_conn_pragmas(0, schema::DEFAULT_CACHE_BUDGET_KB);
        assert!(
            sql.contains("cache_size = -8192"),
            "0 conns should fallback to 8MB: {sql}"
        );
    }

    #[test]
    fn pooled_connections_observe_configured_and_runtime_journal_size_limits() {
        const CONFIGURED_LIMIT: i64 = 1_048_577;
        const RETUNED_LIMIT: i64 = 2_097_153;

        let configured_limit = CONFIGURED_LIMIT.to_string();
        mcp_agent_mail_core::config::with_process_env_overrides_for_test(
            &[("DB_JOURNAL_SIZE_LIMIT_BYTES", configured_limit.as_str())],
            || {
                let directory = tempfile::tempdir().expect("tempdir");
                let db_path = directory.path().join("journal-limit.sqlite3");
                let pool = DbPool::new_without_startup_init(&DbPoolConfig {
                    database_url: format!("sqlite:///{}", db_path.display()),
                    storage_root: Some(directory.path().join("archive")),
                    min_connections: 0,
                    max_connections: 2,
                    run_migrations: false,
                    warmup_connections: 0,
                    ..Default::default()
                })
                .expect("create journal-limit pool");
                let final_pragma = format!("PRAGMA journal_size_limit = {CONFIGURED_LIMIT};");
                assert!(
                    pool.init_sql.trim_end().ends_with(final_pragma.as_str()),
                    "operator limit must be the authoritative final connection-init assignment: {}",
                    pool.init_sql
                );

                let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
                    .build()
                    .expect("build runtime");
                let cx = asupersync::Cx::for_testing();
                runtime.block_on(async {
                    let original = pool
                        .acquire(&cx)
                        .await
                        .into_result()
                        .expect("acquire initially configured connection");
                    assert_eq!(
                        read_pragma_i64(
                            &original,
                            "PRAGMA journal_size_limit;",
                            "journal_size_limit",
                        )
                        .expect("read configured journal_size_limit"),
                        CONFIGURED_LIMIT
                    );

                    pool.set_journal_size_limit(RETUNED_LIMIT.unsigned_abs())
                        .expect("retune pool journal_size_limit");
                    let newly_opened = pool
                        .acquire(&cx)
                        .await
                        .into_result()
                        .expect("acquire newly opened connection after retune");
                    assert_eq!(
                        read_pragma_i64(
                            &newly_opened,
                            "PRAGMA journal_size_limit;",
                            "journal_size_limit",
                        )
                        .expect("read retuned limit on new connection"),
                        RETUNED_LIMIT
                    );

                    // The only idle handle is the connection that was active
                    // during the retune, so this acquisition causally proves
                    // checkout repairs that stale connection-local setting.
                    drop(original);
                    let recycled_original = pool
                        .acquire(&cx)
                        .await
                        .into_result()
                        .expect("reacquire connection that spanned retune");
                    assert_eq!(
                        read_pragma_i64(
                            &recycled_original,
                            "PRAGMA journal_size_limit;",
                            "journal_size_limit",
                        )
                        .expect("read retuned limit on recycled connection"),
                        RETUNED_LIMIT
                    );
                    drop(recycled_original);
                    drop(newly_opened);
                });
            },
        );
    }

