        conn.execute_raw("CREATE TABLE t (x INTEGER)")
            .expect("create table");
        drop(conn);

        // A 0-byte WAL sidecar is a valid idle/checkpointed WAL-mode state.
        let wal_path = dir.path().join("cleanup_test.db-wal");
        std::fs::write(&wal_path, b"").expect("create empty wal");
